from openpyxl import load_workbook

# 目標：在「料表」中以第1列合併群組「B 廠」定位其下的「M/S」欄，
# 把該欄不等於「OK」的資料列（A~H）複製到新工作表，表頭沿用第2列。

wb = load_workbook(INPUT_PATH)
ws = wb["料表"]

header_row = 2

# 1. 依第1列的合併儲存格建立「欄位 → 區塊名」對照
group_names = {}
for rng in ws.merged_cells.ranges:
    if rng.min_row <= 1 <= rng.max_row:
        title = ws.cell(rng.min_row, rng.min_col).value
        for col in range(rng.min_col, rng.max_col + 1):
            group_names[col] = title

# 2. 讀取第2列欄名
headers = {col: ws.cell(header_row, col).value for col in range(1, ws.max_column + 1)}

# 3. 找出「B 廠」區塊的「M/S」欄
target_col = None
for col, name in headers.items():
    if name == "M/S" and group_names.get(col) == "B 廠":
        target_col = col
        break

if target_col is None:
    raise ValueError("找不到「B 廠」區塊的「M/S」欄")

# 4. 建立新工作表
new_title = "B廠異常"
if new_title in wb.sheetnames:
    i = 1
    while f"{new_title}_{i}" in wb.sheetnames:
        i += 1
    new_title = f"{new_title}_{i}"
new_ws = wb.create_sheet(title=new_title)

# 5. 複製表頭（第2列）
for col in range(1, ws.max_column + 1):
    new_ws.cell(row=1, column=col, value=headers[col])

# 6. 複製 M/S 不等於 "OK" 的整列
dest_row = 2
for row in range(header_row + 1, ws.max_row + 1):
    if ws.cell(row, target_col).value != "OK":
        for col in range(1, ws.max_column + 1):
            new_ws.cell(row=dest_row, column=col, value=ws.cell(row, col).value)
        dest_row += 1

wb.save(OUTPUT_PATH)
