# 推斷：資料表=主件表（表頭第2列）｜欄位=我方確認.檢驗結果｜篩選=值不為「OK」｜輸出=新工作表「我方確認_檢驗異常」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb['主件表']

header_row = 2

# 用第 1 列的合併群組標題消歧，建立每欄所屬群組
group_titles = {}
for merged in ws.merged_cells.ranges:
    if merged.min_row == 1 and merged.max_row == 1:
        title = ws.cell(row=1, column=merged.min_col).value
        for col in range(merged.min_col, merged.max_col + 1):
            group_titles[col] = title

# 找出「我方確認」區的「檢驗結果」欄位
target_col = None
headers = {}
for col in range(1, ws.max_column + 1):
    val = ws.cell(row=header_row, column=col).value
    headers[col] = val
    if group_titles.get(col) == '我方確認' and val == '檢驗結果':
        target_col = col

if target_col is None:
    raise ValueError("找不到「我方確認」區的「檢驗結果」欄位")

# 篩選檢驗結果非「OK」的資料列
filtered_rows = []
for row in range(header_row + 1, ws.max_row + 1):
    result = ws.cell(row=row, column=target_col).value
    if result is not None and str(result).strip().upper() != 'OK':
        filtered_rows.append(row)

# 建立新工作表
new_ws_name = '我方確認_檢驗異常'
if new_ws_name in wb.sheetnames:
    n = 2
    while f'{new_ws_name}_{n}' in wb.sheetnames:
        n += 1
    new_ws_name = f'{new_ws_name}_{n}'

new_ws = wb.create_sheet(title=new_ws_name)

# 複製表頭（第 2 列）
for col in range(1, ws.max_column + 1):
    new_ws.cell(row=1, column=col, value=headers[col])

# 複製篩選後的資料列
for r_idx, src_row in enumerate(filtered_rows, start=2):
    for col in range(1, ws.max_column + 1):
        new_ws.cell(row=r_idx, column=col, value=ws.cell(row=src_row, column=col).value)

wb.save(OUTPUT_PATH)
