# 推斷：資料表=BOM（表頭第2列）｜欄位=本廠狀態（第2列「狀態」配合第1列群組「本廠」）｜主檔=BOM｜鍵=列號｜篩選=本廠狀態≠"OK"｜輸出=新工作表
from openpyxl import load_workbook

wb = load_workbook(INPUT_PATH)
ws = wb["BOM"]

# 1. 建立第1列的群組標籤對照（處理合併儲存格）
group_labels = {}
for col in range(1, ws.max_column + 1):
    group_labels[col] = ws.cell(row=1, column=col).value

for merged_range in ws.merged_cells.ranges:
    if merged_range.min_row <= 1 <= merged_range.max_row:
        top_left_value = ws.cell(
            row=merged_range.min_row, column=merged_range.min_col
        ).value
        for col in range(merged_range.min_col, merged_range.max_col + 1):
            group_labels[col] = top_left_value

# 2. 建立第2列欄名對照，遇到重複欄名時用第1列群組標籤消歧
headers = {col: ws.cell(row=2, column=col).value for col in range(1, ws.max_column + 1)}
header_counts = {}
for h in headers.values():
    if h:
        header_counts[h] = header_counts.get(h, 0) + 1

col_map = {}
for col, h in headers.items():
    if header_counts.get(h, 0) > 1:
        group = group_labels.get(col) or ""
        key = f"{group}_{h}" if group else h
    else:
        key = h
    col_map[key] = col

# 3. 定位「本廠」的「狀態」欄
target_col = None
for key, col in col_map.items():
    if key == "本廠_狀態":
        target_col = col
        break

if target_col is None:
    raise ValueError("找不到「本廠」的「狀態」欄位")

# 4. 建立新工作表
new_title = "本廠狀態非OK"
while new_title in wb.sheetnames:
    new_title += "_1"
new_ws = wb.create_sheet(title=new_title)

# 5. 複製表頭（第2列）
header_values = [ws.cell(row=2, column=col).value for col in range(1, ws.max_column + 1)]
new_ws.append(header_values)

# 6. 篩選「本廠」「狀態」不是 "OK" 的整列資料並複製
for row in range(3, ws.max_row + 1):
    status = ws.cell(row=row, column=target_col).value
    if str(status).strip() != "OK":
        row_values = [
            ws.cell(row=row, column=col).value for col in range(1, ws.max_column + 1)
        ]
        new_ws.append(row_values)

wb.save(OUTPUT_PATH)
```

