```python
# 推斷：資料表=機構件/附件/電子件（表頭第 1 列）｜合併三表到新工作表｜目標欄位=來源表 + 機構件欄位順序

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 定義目標欄位順序（以機構件為準，前面加上來源表）
target_headers = ['來源表', '項次', '單位', '數量', '料號', '類別', '品名']

# 各工作表的欄位映射（欄名→目標索引）
# 機構件：項次 | 單位 | 數量 | 料號 | 類別 | 品名
sheet_機構件_map = {'項次': 1, '單位': 2, '數量': 3, '料號': 4, '類別': 5, '品名': 6}

# 附件：項次 | 品名 | 單位 | 料號 | 類別 | 數量
sheet_附件_map = {'項次': 1, '品名': 6, '單位': 2, '料號': 4, '類別': 5, '數量': 3}

# 電子件：項次 | 類別 | Dri | 單位 | 數量 | 料號 | 品名（Dri 欄位捨棄）
sheet_電子件_map = {'項次': 1, '類別': 5, '單位': 3, '數量': 4, '料號': 5, '品名': 6}
# 修正電子件映射：A=項次，B=類別，C=Dri, D=單位，E=數量，F=料號，G=品名
sheet_電子件_map = {'項次': 1, '類別': 2, '單位': 4, '數量': 5, '料號': 6, '品名': 7}

def get_sheet_data(sheet_name, col_map):
    """從工作表讀取數據並對齊到目標欄位"""
    ws = wb[sheet_name]
    data = []

    # 讀取表頭列，建立欄名→實際列索引對照
    headers = {}
    for col_idx, cell in enumerate(ws[1], start=1):
        if cell.value:
            headers[cell.value] = col_idx

    # 讀取數據列（從第 2 列開始）
    for row_idx in range(2, ws.max_row + 1):
