import openpyxl

# 載入工作簿
wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["主件表"]

# 自動定位表頭列：包含 項次/料號/品名 者為上層表頭；其後第一個出現「外觀」者為下層表頭
top_header_row = None
for r in range(1, ws.max_row + 1):
    row_vals = [ws.cell(row=r, column=c).value for c in range(1, ws.max_column + 1)]
    row_strs = [str(v).strip() if v is not None else "" for v in row_vals]
    if "項次" in row_strs and "料號" in row_strs and "品名" in row_strs:
        top_header_row = r
        break

sub_header_row = None
if top_header_row:
    for r in range(top_header_row + 1, ws.max_row + 1):
        for c in range(1, ws.max_column + 1):
            v = ws.cell(row=r, column=c).value
            if v is not None and str(v).strip() == "外觀":
                sub_header_row = r
                break
        if sub_header_row:
            break

# 若找不到下層表頭，視為單層表頭
if sub_header_row is None:
    sub_header_row = top_header_row
data_start_row = sub_header_row + 1

# 建立有效欄名對照：
# - 上層為群組標題（合併儲存格）或空者，取下層欄名
# - 其餘取上層欄名
col_name_to_idx = {}
for c in range(1, ws.max_column + 1):
    v_top = ws.cell(row=top_header_row, column=c).value
    v_sub = ws.cell(row=sub_header_row, column=c).value

    is_group = False
    for rng in ws.merged_cells.ranges:
        if rng.min_row <= top_header_row <= rng.max_row and rng.min_col <= c <= rng.max_col:
            is_group = True
            break

    if is_group or v_top is None or str(v_top).strip() == "":
        name = v_sub
    else:
        name = v_top

    if name is not None:
        col_name_to_idx[str(name).strip()] = c

# 目標欄位
target_cols = ["項次", "料號", "品名", "外觀"]
col_idx = {name: col_name_to_idx[name] for name in target_cols}

# 篩選「外觀」不是 "ok" 的資料列
filtered = []
for r in range(data_start_row, ws.max_row + 1):
    app_val = ws.cell(row=r, column=col_idx["外觀"]).value
    if app_val is None:
        continue
    if str(app_val).strip().lower() != "ok":
        filtered.append([ws.cell(row=r, column=col_idx[name]).value for name in target_cols])

# 建立新工作表並寫入結果
new_name = "外觀非OK"
if new_name in wb.sheetnames:
    del wb[new_name]
new_ws = wb.create_sheet(title=new_name)
new_ws.append(target_cols)
for row in filtered:
    new_ws.append(row)

# 儲存結果
wb.save(OUTPUT_PATH)
